const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let entries=[],selected=null,currentId='';
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();return {ok:r.ok,status:r.status,data};}
function display(verdict,reason,metrics=''){ $('#verdict').textContent=verdict;$('#reason').textContent=reason;$('#metrics').textContent=metrics;}
function renderEntry(e){selected=e;$('#bundle').href='/v0/bundles/'+encodeURIComponent(e.id)+'.tar.gz';const recorded=e.replay.status==='recorded';$('#replay-lamp').className='lamp'+(recorded?' recorded':'');$('#replay-lamp').textContent=recorded?'● Recorded replay — not re-run by fvapi':'● Real replay — independently re-check the bundle';$('#entry').innerHTML=`<h3>${esc(e.title)}</h3><p class="claim">${esc(e.claim)}</p>${recorded?'<p class="notice">Recorded stub. This proof was not re-run by fvapi. The transcript comes from an earlier run.</p>':''}<div class="entry-grid"><div><h4>Statements to verify</h4>${e.statements.map(s=>`<p>${esc(s.name)} <small>${esc(s.file)}:${s.line}</small></p><pre>${esc(s.text)}</pre>`).join('')}<h4>Delivered files and SHA-256</h4><table><thead><tr><th>File</th><th>SHA-256 / bytes</th></tr></thead><tbody>${e.closure.map(f=>`<tr><td>${esc(f.path)}</td><td><code>${esc(f.sha256)}</code><br>${f.bytes} bytes</td></tr>`).join('')}</tbody></table></div><div><h4>Replay on your machine</h4><pre id="command">${esc(e.replay.command)}</pre><button class="copy" id="copy-command">Copy replay command</button><dl><dt>Expected axioms</dt><dd>${esc(e.replay.expect_axioms.join(', ')||'None')}</dd><dt>Toolchain / requirements</dt><dd>${esc(e.toolchain)}<br>${esc(e.requires.join(', '))}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(t=>`${esc(t.name)}: ${esc(t.spdx)}<br>${esc(t.source)}`).join('<br>'):'No third-party notices in this manifest.'}</dd><dt>Source</dt><dd>${esc(e.source.repo)}<br>Commit ${esc(e.source.commit)}<br>${e.source.paths.map(esc).join('<br>')}</dd></dl>${recorded?`<h4>Recorded transcript</h4><pre>${esc(e.replay.transcript||e.replay.note)}</pre>`:''}</div></div>`;$('#copy-command').onclick=async()=>{try{await navigator.clipboard.writeText(e.replay.command);$('#copy-command').textContent='Command copied';}catch{$('#copy-command').textContent='Select and copy the command above';}};$('#input').value=e.check?JSON.stringify(e.check.example_input,null,2):'{}';$('#input-note').textContent=e.check?'Edit this JSON, then run the checker.':'This entry has no checker. Run check returns 409.';}
async function select(id){currentId=id;display('READY','Select an input. Run the checker.','No check submitted for this entry');$('#bundle').href='/v0/bundles/'+encodeURIComponent(id)+'.tar.gz';document.querySelectorAll('.switch').forEach(b=>b.setAttribute('aria-pressed',b.dataset.id===id));const r=await api('catalog/'+encodeURIComponent(id));if(r.ok)renderEntry(r.data);else{const e=entries.find(e=>e.id===id);selected=null;$('#entry').innerHTML=`<h3>${esc(e?.title||id)}</h3><p>${esc(e?.claim||r.data.detail)}</p><p class="notice">Recorded stub — not re-run by fvapi. Full manifest unavailable in this mock.</p>`;$('#replay-lamp').textContent='● Recorded — not re-run by fvapi';$('#input').value='{}';}}
async function logs(mode='answers'){const r=await api(mode);$('#log-title').textContent=mode==='demand'?'Demand / unmatched requests':'Answers / instrument records';const records=mode==='demand'?r.data.misses:r.data.answers;$('#log').innerHTML=(records?.length?records.map(x=>`<div class="record"><pre>${esc(JSON.stringify(x,null,2))}</pre></div>`).join(''):'<p>No records. Run a lookup or a check.</p>')+(mode==='demand'?`<h3>Counts by key</h3>${(r.data.by_key||[]).map(x=>`<div class="record">${esc(x.key)}<br>Count: ${x.count}</div>`).join('')}`:'');}
async function lookup(){const value=$('#query').value;const r=await api('lookup',{spec_id:value});$('#lookup-status').textContent=r.ok?'Match found. Inspect the proof package below.':r.status===404?'No match. Logged as demand. Try another specification.':`${r.data.detail} Edit the specification and try again.`;display(r.ok?'FOUND':'NO MATCH',r.ok?'Proof package available':'Logged as demand',`Lookup / HTTP ${r.status}`);if(r.ok){const id=r.data.entry?.id||r.data.entry_id||r.data.id||value;await select(id);display('FOUND','Proof package available',`Lookup / HTTP ${r.status}`);}await logs();}
async function check(){let input;try{input=JSON.parse($('#input').value);}catch{display('INPUT ERROR','Invalid JSON. Correct the input and run again.');return;}const r=await api('checks/'+encodeURIComponent(currentId),input);if(r.ok)display(r.data.verdict.toUpperCase(),r.data.output.reason,`${r.data.elapsed_ms} ms / ${r.data.ran_on} / exit ${r.data.exit_code}`);else display(r.status===409?'NO CHECKER':'ERROR',r.data.error,`${r.data.detail} Select a checker to run input.`);if(r.ok&&r.data.recheck){$('#input-note').textContent='Re-check locally: '+r.data.recheck.command;}await logs();}
$('#lookup-form').onsubmit=e=>{e.preventDefault();lookup().catch(failure);};$('#run').onclick=()=>check().catch(failure);$('#example').onclick=()=>{if(selected?.check)$('#input').value=JSON.stringify(selected.check.example_input,null,2);else display('NO CHECKER','Select a checker to load an example.');};$('#answers').onclick=()=>logs('answers').catch(failure);$('#demand').onclick=()=>logs('demand').catch(failure);function failure(e){display('OFFLINE','Cannot reach the API. Reload to try again.');$('#lookup-status').textContent=e.message;}
async function init(){const r=await api('catalog');entries=r.data.entries;$('#catalog').innerHTML=entries.map(e=>`<button class="switch" data-id="${esc(e.id)}" aria-pressed="false"><b>${esc(e.subject.name)}</b><small>${esc(e.title)}</small><em>${esc(e.kind)} / ${esc(e.replay_status)}</em></button>`).join('');document.querySelectorAll('.switch').forEach(b=>b.onclick=()=>select(b.dataset.id).catch(failure));const state=new URLSearchParams(location.search).get('state')||'catalog';await select(state==='recorded'||state==='check-409'?'fva.glm-iround':'vf.contrast-2x2');await logs();if(state==='lookup-hit'||state==='lookup-miss'){$('#query').value=state==='lookup-hit'?'vf.contrast-2x2':'unmatched.example';await lookup();}if(['check-accept','check-reject','check-409'].includes(state)){if(state==='check-reject'){const input=JSON.parse($('#input').value);input.rows[1].weights[0]+=1;$('#input').value=JSON.stringify(input,null,2);}await check();}if(state==='demand')await logs('demand');if(['entry','recorded'].includes(state))$('#entry').scrollIntoView({block:'start'});if(['demand','answers'].includes(state))$('.recorder').scrollIntoView({block:'start'});document.body.dataset.ready='true';}init().catch(failure);
